-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["48329bb2d723ab11"] = { "Posso solo immaginare perché sono sopravvissuto quella notte. Sono sempre stato prudente, sempre pronto a scansare i colpi e a evitare le trappole con un balzo. Il mio soprannome viene da questo tratto. Così forse è stata proprio quella dote di prudenza a salvarmi...\n\nO forse è stata la Falce che ho estratto dalle macerie. Non può essere la Falce in sé, perché l'ho persa durante la mia fuga disperata. Ma se sono stato io a portare i worgen a ⟦Duskwood=Boscovespro⟧, forse i worgen mi hanno concesso una rara cortesia. Che siano maledetti.", "." },
  ["4858f66707a9f824"] = { "Buona fortuna. Ed ecco un indizio che potrebbe aiutarti nelle prove contro i servitori di Urok:\n\nIl sortilegio che Omokk usa contro gli ogre, quello che li uccide all'istante, potrebbe conservare il suo potere anche dopo che avrai ucciso Omokk. Durante lo scontro con i servitori di Urok, invoca il potere della testa di Omokk: con un po' di fortuna, Omokk abbatterà i servitori di Urok!\n\nUn'ironia che calza a pennello.", "." },
  ["4859f6f4a4857033"] = { "Dopo il successo di Kel'Thuzad a Lordaeron, il Re dei Lich compì gli ultimi preparativi per il suo assalto alla civiltà umana. Riversate le sue energie pestilenziali in una serie di manufatti trasportabili chiamati calderoni della pestilenza, Ner'zhul ordinò a Kel'Thuzad di portarli a Lordaeron, dove sarebbero stati nascosti in vari villaggi controllati dal culto.", "." },
  ["489579a033cd7a8c"] = { "Mentre il Re dei Lich affinava le sue crescenti capacità sotto l'assidua sorveglianza dei signori del terrore, scoprì un remoto insediamento umano ai margini del vasto Dragonblight. Per capriccio, Ner'zhul decise di mettere alla prova i suoi poteri sugli ignari umani.", "." },
  ["48962658def204fd"] = { "Scorgendo il mondo primordiale di Azeroth e percependo le energie illimitate del ⟦Well of Eternity=Pozzo dell'Eternità⟧, Sargeras fu divorato da una fame insaziabile. Il grande dio oscuro del Vuoto Senza Nome decise di distruggere il giovane mondo e di prenderne le energie per sé.", "." },
  ["4896980d431ed8db"] = { "Lord Stoutmantle,\n\nla municipalità di ⟦Lakeshire=Borgolago⟧ chiede umilmente l'aiuto della vostra milizia. Mentre scrivo, siamo assediati sia dagli orchi ⟦Blackrock=Roccianera⟧ sia dagli gnoll Mantombroso di Morganth. Non vi manderei questa richiesta se la nostra situazione non fosse grave. Attendiamo aiuti da ⟦Stormwind=Roccavento⟧, ma finché non arriveranno vi supplico di darci il vostro sostegno. Se il regno verrà violato, l'intera umanità sarà in pericolo.\n\n⟦Magistrate Solomon=Magistrato Solomon⟧", "." },
  ["48b3402fdf347d79"] = { "Il resto delle tribù Gurubashi prese strade separate, dopo che la grande guerra civile aveva lasciato in rovina le loro terre. Le tribù Fendicranio, Scalporosso e ⟦Darkspear=Lanciascura⟧ partirono per rivendicare terre proprie nelle vaste giungle di Rovotorto. Benché sull'impero frantumato fosse calata una fragile pace, alcuni parlavano di una profezia secondo cui un giorno Hakkar sarebbe rinato nel mondo, e quel giorno lo avrebbe divorato per intero.", "." },
  ["48c04b38cdd29d65"] = { "Capitolo 4 - I fortilizi di Dun Baldar\n\nCome avrai senz'altro notato, gli strati difensivi dei Piccatonante servono a impedire che un'unica mossa di forza smantelli l'intero esercito. Prima che tu lo chieda: sì, le nostre forze sono disposte esattamente così, e no, non cambierò la nostra struttura difensiva. Sono loro che ci hanno copiato, perché dovremmo cambiare noi?", "." },
})
